import { useEffect, useMemo, useRef, useState } from "react";
import {
  ActionType,
  Dispatchable,
  SelectablePass,
  SelectedUpsellProduct,
} from "@/core/types/state/group-admission/group-admission-types";
import { ITimeSlot } from "@/core/types/time-slots";
import styles from "./upsell-item.module.less";
import { isNonEmptyArray, DateHelper, CurrencyHelper, multipleClassNames } from "@/core/helpers";
import { AnimatePresence, Variants, motion } from "framer-motion";
import { TimeSlotRadioButtonList } from "@/core/components/modules/time-slot-list/time-slot-list";
import { OutlineButton, PrimaryButton } from "@/core/components/primitives/parks-button/parks-button";
import RichText from "@/core/components/primitives/rich-text/rich-text";
import TopSection from "./top-section/top-section";
import { filterTimeSlotsOnSelectedEntryTimeSlot } from "../upsell-functions";
import animatedScrollTo from "animated-scroll-to";
import { useTranslation } from "react-i18next";
import ExpandContent from "@/core/components/primitives/expand-content/expand-content";
import { useShakeable } from "@/core/hooks/use-shakeable";
import { useShopServiceCartContext } from "@/core/contexts";
import { useProduct } from "@/core/hooks/product-hooks";

type UpsellItemProps = {
  upsellProductId: number;
  totalGroupSize: number;
  timeSlots: Array<ITimeSlot>;
  selectedUpsellProduct?: SelectedUpsellProduct;
  selectedEntryTimeSlot: SelectablePass;
  selectedDate: Date;
  isDisabled: boolean;
} & Dispatchable;

export const animateExpandCollapseContent: Variants = {
  initial: {
    height: 0,
    opacity: 0,
  },
  expandContent: {
    height: "auto",
    opacity: 1,
    overflow: "visible",
    display: "block",
    transition: {
      opacity: { delay: 0.05, duration: 0.3 },
      height: { duration: 0.2, type: "tween" },
    },
  },
  collapseContent: {
    overflow: "hidden",
    height: 0,
    opacity: 0,
    transition: {
      opacity: { duration: 0.2 },
      height: { duration: 0.2, type: "tween" },
    },
    transitionEnd: { display: "none" },
  },
};

const summarizePrice = (price: number, quantity: number) => {
  return price * quantity;
};

const getNearestAvailableTimeSlot = (timeSlots: Array<ITimeSlot>) => {
  if (!isNonEmptyArray(timeSlots)) {
    return null;
  }

  const filteredTimeSlotsQuantities = timeSlots.filter((slot) => slot.quantity > 0);
  const nearestBookableTimeSlot = isNonEmptyArray(filteredTimeSlotsQuantities)
    ? DateHelper.toStringTimeHHMM(filteredTimeSlotsQuantities[filteredTimeSlotsQuantities.length - 1].timeSlotFrom)
    : null;

  return nearestBookableTimeSlot;
};

const getMaxQuantity = (
  totalGroupSize: number,
  productQuantityInCart: number,
  maximumQuantity: number | undefined | null,
) => {
  maximumQuantity ??= 0;
  if (maximumQuantity > 0) {
    const maximumCartProductQuantity = maximumQuantity - productQuantityInCart;
    if (maximumCartProductQuantity >= 0) {
      return maximumCartProductQuantity;
    }
  }

  return totalGroupSize;
};

const UpsellItem = ({
  upsellProductId,
  totalGroupSize,
  timeSlots,
  selectedUpsellProduct,
  selectedEntryTimeSlot,
  selectedDate,
  isDisabled,
  dispatch,
}: UpsellItemProps) => {
  const wrapperRef = useRef<HTMLDivElement | null>(null);
  const [selectedQuantity, setSelectedQuantity] = useState<number | null>(null);
  const [showQuantitySelector, setShowQuantitySelector] = useState(false);
  const [showAddButton, setShowAddButton] = useState(true);
  const [isExpanded, setIsExpanded] = useState(false);
  const [selectedTimeSlot, setSelectedTimeSlot] = useState<ITimeSlot | null>(null);
  const [confirmLoader, setConfirmLoader] = useState(false);
  const [Shakeable, shake] = useShakeable({
    rotationDegrees: 2,
    shakesPerRepeat: 2,
    durationPerRepeat: 1000,
    repeat: 2,
    repeatDelay: 2000,
  });

  const product = useProduct(upsellProductId);
  const { data: cartData } = useShopServiceCartContext();

  const productQuantityInCart = useMemo(
    () =>
      cartData?.cartItems.filter((item) => item.productId === upsellProductId).reduce((a, b) => a + b.quantity, 0) ?? 0,
    [cartData, upsellProductId],
  );

  const maxQuantity = getMaxQuantity(totalGroupSize, productQuantityInCart, product?.glkProduct?.maximumQuantity);

  // Determine if the upsell limit is already met.
  // maxQuantity is the remaining amount the user can add (after subtracting items in the cart).
  // If it's 0 and the cart already has this product, no more units can be added.
  const maxQuantityReached = productQuantityInCart > 0 && maxQuantity === 0;

  const { t } = useTranslation();

  const nearestAvailableTimeSlot = isDisabled ? getNearestAvailableTimeSlot(timeSlots) : null;
  const isSoldOut = isDisabled && !nearestAvailableTimeSlot;

  const filteredTimeSlots = useMemo(() => {
    if (selectedEntryTimeSlot && timeSlots && !product?.contentfulProduct?.purchasableOutsideEntryTime) {
      return filterTimeSlotsOnSelectedEntryTimeSlot(timeSlots, selectedEntryTimeSlot);
    }
    if (selectedEntryTimeSlot && timeSlots && product?.contentfulProduct?.purchasableOutsideEntryTime) {
      return timeSlots;
    }
    return timeSlots;
  }, [selectedEntryTimeSlot, timeSlots, product?.contentfulProduct?.purchasableOutsideEntryTime]);

  useEffect(() => {
    if (selectedQuantity && selectedQuantity > 0) {
      setIsExpanded(true);
    } else {
      setIsExpanded(false);
    }
  }, [selectedQuantity]);

  const animateCollapse = () => {
    if (!wrapperRef.current) {
      console.warn("Wrapper ref is not set, cannot perform animated collapse.");
      return;
    }
    const rect = wrapperRef.current.getBoundingClientRect();

    if (rect.top < 54) {
      // Scrollat förbi toppen av upsell-itemet - hjälp till o scrolla tillbaka så inte expandern förvirrar
      animatedScrollTo(wrapperRef.current, { verticalOffset: -68, speed: 1000 }).then(() => {
        setIsExpanded(false);
      });
    } else {
      setIsExpanded(false);
    }
  };

  const onClickConfirmButton = () => {
    const selectedUpsellProduct: SelectedUpsellProduct = {
      productId: upsellProductId,
      timeSlot: selectedTimeSlot ?? undefined,
      quantity: selectedQuantity ?? 0,
    };

    setConfirmLoader(true);

    // Simulate a loading state that shows the user that the product is being added
    setTimeout(() => {
      setConfirmLoader(false);
      dispatch({
        type: ActionType.UPDATE_UPSELL_PRODUCT,
        payload: { upsellProduct: selectedUpsellProduct, selectedDate: selectedDate },
      });
      setShowQuantitySelector(false);
    }, 1500);
  };

  const removeSelectedProduct = () => {
    dispatch({
      type: ActionType.DELETE_UPSELL_PRODUCT,
      payload: { productId: upsellProductId, date: selectedDate },
    });
  };

  const clearProductState = () => {
    setSelectedQuantity(0);
    setSelectedTimeSlot(null);
    setShowAddButton(true);
    setShowQuantitySelector(false);
  };

  const onClickCancelButton = () => {
    animateCollapse();
    clearProductState();
    removeSelectedProduct();
  };

  const onChangeQuantity = (updatedQuantity: number) => {
    setSelectedQuantity(updatedQuantity);

    if (selectedTimeSlot && selectedTimeSlot.quantity < updatedQuantity) {
      setSelectedTimeSlot(null);
      return;
    }

    if (updatedQuantity === 0) {
      clearProductState();
      removeSelectedProduct();
    }
  };

  const onClickTimeSlot = (selectedTimeSlot: ITimeSlot) => {
    setSelectedTimeSlot(selectedTimeSlot);
  };

  const unitPrice = product?.glkProduct.priceIncludingVat ?? 0;
  const totalPrice = summarizePrice(unitPrice, selectedQuantity ?? 0);
  const hasSelectedQuantity = typeof selectedQuantity === "number" && selectedQuantity > 0;
  const isAddButtonDisabled = !hasSelectedQuantity || (isNonEmptyArray(filteredTimeSlots) && !selectedTimeSlot);

  //The remove button is redundant when we show the quantity selector (since we then have a minus button)
  // hence having !showQuantitySelector
  const showRemoveButton = selectedUpsellProduct && hasSelectedQuantity && !showQuantitySelector;

  const priceSpan = {
    labelId: product?.contentfulProduct?.purchaseFlowCustomPriceText
      ? "purchaseFlowCustomPriceText in ProductBlock"
      : "defaultProductUnit",
    unitPrice: CurrencyHelper.formatToSek(unitPrice),
    perUnitText: product?.contentfulProduct?.purchaseFlowCustomPriceText || t("defaultProductUnit"),
  };

  return (
    <div
      ref={wrapperRef}
      className={multipleClassNames(
        styles.wrapper,
        showQuantitySelector && styles.selected,
        product?.contentfulProduct?.componentTheme,
      )}
      data-testid={`upsell-${upsellProductId}`}
    >
      <div className={styles.selectedOutline}></div>
      <div className={styles.border}>
        <div className={styles.innerWrapper}>
          <AnimatePresence mode="sync">
            <TopSection
              upsellProductId={upsellProductId}
              isSoldOut={isSoldOut}
              maximumQuantityReached={maxQuantityReached}
              selectedEntryTimeSlot={selectedEntryTimeSlot}
              nearestAvailableTimeSlot={nearestAvailableTimeSlot ?? undefined}
              onClickOpenProduct={() => {
                setShowQuantitySelector(true);
                onChangeQuantity(1);
                setSelectedQuantity(1);
                setShowAddButton(false);
                if (product?.glkProduct.metadata?.autoSelectTimeslot) {
                  setSelectedTimeSlot(filteredTimeSlots[0]);
                }
                shake();
              }}
              showQuantitySelector={showQuantitySelector}
              showAddButton={showAddButton}
              onChangeQuantity={onChangeQuantity}
              quantity={selectedQuantity ?? 0}
              maxQuantity={maxQuantity}
              quantityInCart={productQuantityInCart}
            />
            <motion.div
              key="expand-wrapper"
              className={styles.expandWrapper}
              initial={false}
              animate={isExpanded ? "expandContent" : "collapseContent"}
              variants={animateExpandCollapseContent}
            >
              <div className={styles.expandInnerWrapper}>
                <div className={styles.summaryAreaWrapper}>
                  {typeof selectedQuantity === "number" && selectedQuantity > 0 && !showQuantitySelector && (
                    <div className={styles.quantityWrapper}>
                      <span className={styles.sumLabel} data-contentful-label-id="amount">
                        {t("amount")}
                      </span>
                      <span className={styles.sumValue}>{selectedQuantity}</span>
                    </div>
                  )}
                  {selectedUpsellProduct && selectedUpsellProduct.timeSlot && (
                    <motion.div
                      key="selected-time-wrapper"
                      initial={false}
                      animate={{ height: "auto" }}
                      className={styles.selectedTimeWrapper}
                    >
                      <span className={styles.sumLabel} data-contentful-label-id="chosenTime">
                        {t("chosenTime")}
                      </span>
                      <span className={styles.sumValue}>
                        {DateHelper.toStringTimeHHMM(selectedUpsellProduct?.timeSlot?.timeSlotFrom)}
                      </span>
                    </motion.div>
                  )}
                  {isNonEmptyArray(filteredTimeSlots) &&
                    !product?.glkProduct.metadata?.autoSelectTimeslot &&
                    !selectedUpsellProduct?.timeSlot && (
                      <motion.div
                        key="time-slot-wrapper"
                        initial={false}
                        animate={!showRemoveButton ? "expandContent" : "collapseContent"}
                        variants={animateExpandCollapseContent}
                        className={styles.timeSlotWrapper}
                      >
                        <TimeSlotRadioButtonList
                          listId={DateHelper.toStringYYYYMMDD(selectedDate)}
                          timeSlots={filteredTimeSlots}
                          productId={upsellProductId}
                          attractionId={upsellProductId}
                          attractionName={product?.name ?? "Unknown attraction"}
                          heading={filteredTimeSlots?.length === 1 ? t("time") : t("upsellStepChooseATime")}
                          contentfulLabelId="upsellStepChooseATime"
                          selectedTimeSlotId={selectedTimeSlot?.timeSlotId ?? null}
                          quantity={selectedQuantity ?? 0}
                          showMoreThreshhold={12}
                          onClick={onClickTimeSlot}
                        />
                      </motion.div>
                    )}
                  <div className={styles.totalWrapper}>
                    <span className={styles.sumLabel} data-contentful-label-id="total">
                      {t("total")}
                    </span>
                    <span className={styles.sumValue}>{CurrencyHelper.formatToSek(totalPrice)}</span>
                  </div>
                </div>
                {!selectedUpsellProduct && hasSelectedQuantity && (
                  <motion.div
                    key="button-wrapper"
                    initial={false}
                    exit={{ height: 0 }}
                    className={styles.buttonWrapper}
                  >
                    <OutlineButton
                      isFullWidth={true}
                      label={t("cancel")}
                      contentfulLabelId="cancel"
                      onClick={onClickCancelButton}
                    />
                    <Shakeable>
                      <PrimaryButton
                        className={styles.confirmButton}
                        isFullWidth={true}
                        label={confirmLoader ? t("adding") : t("add")}
                        iconRightNew={confirmLoader ? "loading" : undefined}
                        iconSize="xl"
                        contentfulLabelId="add"
                        isDisabled={isAddButtonDisabled}
                        onClick={onClickConfirmButton}
                      />
                    </Shakeable>
                  </motion.div>
                )}
              </div>
              {showRemoveButton && (
                <motion.div
                  key="remove-button"
                  initial={false}
                  animate={{ height: "auto" }}
                  transition={{ type: "tween" }}
                  exit={{ height: 0 }}
                  className={styles.removeButtonWrapper}
                >
                  <PrimaryButton
                    className={styles.removeButton}
                    isFullWidth={true}
                    onClick={onClickCancelButton}
                    label={t("remove")}
                    contentfulLabelId="remove"
                  />
                </motion.div>
              )}
            </motion.div>
          </AnimatePresence>
          {product?.contentfulProduct?.upsellRichText ? (
            <div className={styles.detailsWrapper}>
              <ExpandContent
                buttonType="ghost"
                buttonPosition="top"
                showMoreLabelOverride={t("showDetails")}
                showLessLabelOverride={t("hideDetails")}
                rightContent={
                  <span className={styles.price} data-contentful-label-id={priceSpan.labelId}>
                    {priceSpan.unitPrice} {priceSpan.perUnitText}
                  </span>
                }
              >
                <div className={styles.detailsContent}>
                  <div className={styles.detailsInnerWrapper}>
                    <div className={styles.editorContent}>
                      <RichText richText={product.contentfulProduct.upsellRichText} />
                    </div>
                  </div>
                </div>
              </ExpandContent>
            </div>
          ) : (
            <span className={styles.priceWithoutDetails} data-contentful-label-id={priceSpan.labelId}>
              {priceSpan.unitPrice} {priceSpan.perUnitText}
            </span>
          )}
        </div>
      </div>
    </div>
  );
};

export default UpsellItem;
