import { DateHelper } from "@/core/helpers";
import { TimeSlotService } from "@/core/services";
import { SelectablePass } from "@/core/types/state/group-admission/group-admission-types";
import { ITimeSlot } from "@/core/types/time-slots";
import { ProductMenuResponse } from "@/core/types/services/time-slot-service";
import { GlkBackedProduct } from "@/core/hooks/product-hooks";
import { WebshopProductType } from "@parksandresorts/webapiproxy-types";

export const getTimeSlotsForAllUpsellProductTypes = async (products: Array<GlkBackedProduct>, selectedDate: Date) => {
  const dateAsString = DateHelper.toStringYYYYMMDD(selectedDate);
  return Promise.all(
    products.map(async (product) => {
      if (product.glkProduct.productType === WebshopProductType.BOOKABLE_TIMESLOT) {
        return await TimeSlotService.getTimeSlots(product.productId, dateAsString);
      }
      return undefined;
    }),
  );
};

export const getTimeSlotsForEachUpsellProductType = (
  product: GlkBackedProduct,
  timeSlotsForProductsForDate: Map<number, ProductMenuResponse> | null,
): Array<ITimeSlot> => {
  const timeSlotsResponse = timeSlotsForProductsForDate?.get(product.productId) ?? [];
  return timeSlotsResponse.flatMap((product) =>
    product.timeslots.map((timeslot) => {
      return {
        productId: product.productId,
        attractionId: product.plcId ?? 0,
        timeSlotId: timeslot.slotId,
        timeSlotFrom: timeslot.slotFrom,
        timeSlotTo: timeslot.slotTo,
        isFullDay: timeslot.isFullDay,
        quantity: timeslot.quantity,
      };
    }),
  );
};

export const filterUpsellTimeSlotsByRideTimeLimits = (
  timeSlots: ITimeSlot[],
  firstRideTimeLimit: string,
  lastRideTimeLimit: string,
) => {
  return timeSlots.filter((timeSlot) => {
    const timeSlotFrom = DateHelper.toStringTimeHHMM(timeSlot.timeSlotFrom);
    const timeSlotTo = DateHelper.toStringTimeHHMM(timeSlot.timeSlotTo);
    const firstRideTime = firstRideTimeLimit.slice(0, -3);
    const lastRideTime = lastRideTimeLimit.slice(0, -3);
    return timeSlotFrom > firstRideTime && timeSlotTo < lastRideTime;
  });
};

export const filterTimeSlotsOnSelectedEntryTimeSlot = (
  timeSlots: ITimeSlot[],
  selectedEntryTimeSlot: SelectablePass,
) => {
  return timeSlots.filter((timeSlot) => DateHelper.isAfter(timeSlot.timeSlotFrom, selectedEntryTimeSlot.timeSlotFrom));
};
