import styles from "./top-section.module.less";
import { DateHelper, insertIntoString, multipleClassNames } from "@/core/helpers";
import { SelectablePass } from "@/core/types/state/group-admission/group-admission-types";
import { PrimaryButton } from "@/core/components/primitives/parks-button/parks-button";
import { AnimatePresence, motion } from "framer-motion";
import Banner from "@/core/components/primitives/banner/banner";
import { Translation } from "@/core/labels/i18n";
import { useTranslation } from "react-i18next";
import QuantitySelectorStyled from "@/core/components/primitives/quantity-selector-styled/quantity-selector-styled";
import { useProduct } from "@/core/hooks/product-hooks";

type TopSectionProps = {
  upsellProductId: number;
  isSoldOut: boolean;
  maximumQuantityReached: boolean;
  selectedEntryTimeSlot: SelectablePass;
  nearestAvailableTimeSlot?: string;
  quantityInCart: number;
  quantity: number;
  maxQuantity: number;
  onChangeQuantity: (updatedQuantity: number) => void;
  onClickOpenProduct: () => void;
  showQuantitySelector: boolean;
  showAddButton: boolean;
};

const getNearestAvailableTimeSlotParagraph = (
  productName: string | undefined,
  selectedEntryTimeSlot: SelectablePass,
  nearestAvailableTimeSlot: string,
  t: Translation,
) => {
  return insertIntoString(t("upsellStepNearestAvailableTimeSlot"), [
    DateHelper.toStringTimeHHMM(selectedEntryTimeSlot.timeSlotFrom),
    productName ?? t("upsellStepGenericProductName"),
    nearestAvailableTimeSlot,
  ]);
};

const TopSection = ({
  upsellProductId,
  isSoldOut,
  maximumQuantityReached,
  selectedEntryTimeSlot,
  nearestAvailableTimeSlot,
  quantity,
  maxQuantity,
  showAddButton,
  showQuantitySelector,
  quantityInCart,
  onChangeQuantity,
  onClickOpenProduct,
}: TopSectionProps) => {
  const { t } = useTranslation();

  const noAvailableTimeSlotForEntryTime = nearestAvailableTimeSlot && selectedEntryTimeSlot;

  const product = useProduct(upsellProductId);
  const imageUrl = product?.contentfulProduct?.productImage?.file?.url;

  return (
    <div className={styles.innerWrapper}>
      <div className={multipleClassNames(styles.topAreaWrapper, !imageUrl && styles.topAreaWrapperNoImage)}>
        <div className={styles.textWrapper}>
          <h5 className={`heading-s ${styles.productName}`}>{product?.name}</h5>
          <p className={styles.shortDescription}>{product?.contentfulProduct?.shortDescription}</p>
        </div>
        {imageUrl && (
          <img
            loading="lazy"
            src={`${imageUrl}?fm=webp&w=200&h=160&fit=pad&q=100`}
            alt={product?.name}
            className={styles.productImage}
          />
        )}
      </div>
      <AnimatePresence mode="sync">
        {(showQuantitySelector || showAddButton) && (
          <div className={styles.buttonWrapper}>
            {showQuantitySelector && (
              <motion.div
                className={styles.quantitySelectorWrapper}
                key="quantity-selector"
                initial={false}
                animate={{ height: "auto" }}
                exit={{ height: 0, opacity: 0 }}
                transition={{ duration: 0.1 }}
              >
                <QuantitySelectorStyled
                  quantity={quantity ? quantity : 0}
                  maxQuantity={maxQuantity}
                  onQuantityChange={onChangeQuantity}
                  label={t("amount")}
                  quantityPresentatorOverride={t("pieces", { count: quantity })}
                />
              </motion.div>
            )}
            {showAddButton && !noAvailableTimeSlotForEntryTime && (
              <motion.div
                key="add-button"
                initial={false}
                animate={{ height: "auto" }}
                exit={{ height: 0 }}
                className={styles.addButtonWrapper}
              >
                <PrimaryButton
                  className={styles.addButton}
                  onClick={onClickOpenProduct}
                  isDisabled={isSoldOut || maximumQuantityReached}
                  isFullWidth={true}
                  label={isSoldOut ? t("soldOut") : t("chooseAmount")}
                  contentfulLabelId={isSoldOut ? "soldOut" : "chooseAmount"}
                  testId="upsell-add-button"
                />
              </motion.div>
            )}
            {noAvailableTimeSlotForEntryTime && (
              <Banner
                type="information"
                heading={t("upsellStepNearestAvailableTimeSlotHeading")}
                paragraph={getNearestAvailableTimeSlotParagraph(
                  product?.name,
                  selectedEntryTimeSlot,
                  nearestAvailableTimeSlot,
                  t,
                )}
              />
            )}
            {maximumQuantityReached && (
              <Banner
                type="information"
                heading={t("upsellStepMaximumQuantityReachedHeading")}
                paragraph={t("upsellStepMaximumQuantityReachedParagraph", { count: quantityInCart })}
              />
            )}
          </div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default TopSection;
